begin;
alter table public.profiles add column if not exists date_of_birth date, add column if not exists age_band text check(age_band is null or age_band in ('13-17','18-24','25-34','35-44','45-54','55+'));
create or replace function unmask_rewards_private.complete_profile(p_name text,p_handle text,p_country text,p_region text,p_age_band text) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid(); begin if u is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'Sign in first'; end if; if not exists(select 1 from auth.users where id=u and email_confirmed_at is not null) then raise exception 'Verify your email first'; end if; if length(trim(p_name)) not between 2 and 40 or p_handle !~ '^[a-z0-9_]{3,24}$' or length(p_country) not between 2 and 100 or length(p_region)>100 then raise exception 'Check your name, username and location'; end if; if p_age_band not in ('13-17','18-24','25-34','35-44','45-54','55+') then raise exception 'Choose a valid age range'; end if; update public.profiles set display_name=trim(p_name),country=p_country,region=p_region,age_band=p_age_band where id=u; insert into public.unmask_public_profiles(user_id,display_name,handle,show_counts) values(u,trim(p_name),p_handle,true) on conflict(user_id) do update set display_name=excluded.display_name,handle=excluded.handle; end; $$;
create or replace function public.unmask_complete_profile(p_name text,p_handle text,p_country text,p_region text,p_age_band text) returns void language sql set search_path='' as $function$ select unmask_rewards_private.complete_profile(p_name,p_handle,p_country,p_region,p_age_band); $function$;
commit;
